    private readonly List<NoteEntry> _notes = [];
    private readonly HttpClient _httpClient;

    public ResearchTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public IReadOnlyList<NoteEntry> Notes => _notes;

    [Description("Searches the web for the given query and returns a list of results with titles, URLs, and snippets.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        try
        {
            // Uses the Brave Search API. Set BRAVE_SEARCH_API_KEY to enable live results.
            var apiKey = Environment.GetEnvironmentVariable("BRAVE_SEARCH_API_KEY");
            if (!string.IsNullOrEmpty(apiKey))
            {
                return await SearchBraveAsync(query, maxResults, apiKey);
            }

            return GenerateSimulatedResults(query, maxResults);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Using simulated results.\n\n"
                + GenerateSimulatedResults(query, maxResults);
        }
    }

    [Description("Saves a research note with a topic label and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("Short topic label for the note")] string topic,
        [Description("The note content to save")] string content)
    {
        var entry = new NoteEntry(topic, content, DateTime.UtcNow);
        _notes.Add(entry);
        return $"Note saved under topic '{topic}'. Total notes: {_notes.Count}.";
    }

    [Description("Retrieves all saved research notes, optionally filtered by topic.")]
    public string GetNotes(
        [Description("Optional topic filter. Leave empty to get all notes.")] string? topicFilter = null)
    {
        var filtered = string.IsNullOrWhiteSpace(topicFilter)
            ? _notes
            : _notes.Where(n => n.Topic.Contains(topicFilter, StringComparison.OrdinalIgnoreCase)).ToList();

        if (filtered.Count == 0)
        {
            return string.IsNullOrWhiteSpace(topicFilter)
                ? "No notes saved yet."
                : $"No notes found matching topic '{topicFilter}'.";
        }

        return string.Join("\n\n", filtered.Select((n, i) =>
            $"--- Note {i + 1} [{n.Topic}] ({n.Timestamp:u}) ---\n{n.Content}"));
    }

    private async Task<string> SearchBraveAsync(string query, int maxResults, string apiKey)
    {
        var requestUri = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count={maxResults}";
        using var request = new HttpRequestMessage(HttpMethod.Get, requestUri);
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Add("Accept", "application/json");

        using var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);

        var results = new List<string>();
        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var webResults))
        {
            foreach (var result in webResults.EnumerateArray().Take(maxResults))
            {
                var title = result.GetProperty("title").GetString();
                var url = result.GetProperty("url").GetString();
                var description = result.TryGetProperty("description", out var desc)
                    ? desc.GetString() : "No description";
                results.Add($"Title: {title}\nURL: {url}\nSnippet: {description}");
            }
        }

        return results.Count > 0
            ? string.Join("\n\n", results)
            : "No results found.";
    }

    private static string GenerateSimulatedResults(string query, int maxResults)
    {
        var results = new List<string>();
        var topics = new[]
        {
            ("Wikipedia", "en.wikipedia.org", "Comprehensive encyclopedia article covering key aspects of"),
            ("Research Paper", "arxiv.org", "Academic paper analyzing recent developments in"),
            ("News Article", "reuters.com", "Latest news coverage and analysis regarding"),
            ("Technical Blog", "techblog.example.com", "In-depth technical exploration of concepts related to"),
            ("Industry Report", "reports.example.com", "Market analysis and industry trends for"),
        };

        for (var i = 0; i < Math.Min(maxResults, topics.Length); i++)
        {
            var (source, domain, snippetPrefix) = topics[i];
            results.Add(
                $"Title: {source}: {query}\n" +
                $"URL: https://{domain}/article/{Uri.EscapeDataString(query.ToLowerInvariant().Replace(' ', '-'))}\n" +
                $"Snippet: {snippetPrefix} {query}. This source provides detailed information including history, current state, and future outlook.");
        }

        return "[Simulated results — set BRAVE_SEARCH_API_KEY for live web search]\n\n"
            + string.Join("\n\n", results);
    }
}

public sealed record NoteEntry(string Topic, string Content, DateTime Timestamp);

