using System.ClientModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

var tools = new ResearchTools(new HttpClient());

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, new ApiKeyCredential(apiKey)));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    """
    You are a research agent. Your job is to research a topic thoroughly and produce a clear summary.

    Workflow:
    1. Search the web for the given topic using multiple queries to cover different angles.
    2. Save important findings as notes using the note-taking tool, organized by sub-topic.
    3. Retrieve your notes and synthesize them into a well-structured summary.
    4. Present the final summary with key findings, organized by theme, with source references.

    Be thorough but concise. Use 2-4 searches to cover the topic well.
    Always save notes before writing the final summary.
    """);

agent.Tools.Add(AIFunctionFactory.Create(tools.SearchWebAsync));
agent.Tools.Add(AIFunctionFactory.Create(tools.SaveNote));
agent.Tools.Add(AIFunctionFactory.Create(tools.GetNotes));

Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (v1.0)       ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine($"Model: {modelId}");
Console.WriteLine("Type a research topic, or 'quit' to exit.");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Research topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
    {
        Console.WriteLine("Goodbye!");
        break;
    }

    Console.WriteLine();
    Console.WriteLine("Researching... (this may take a moment)");
    Console.WriteLine();

    try
    {
        var history = new List<ChatMessage>
        {
            new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
        };

        var options = new AgentInvokeOptions
        {
            MaximumIterations = 10,
        };

        var chatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
        };

        options.AdditionalProperties ??= new();
        options.AdditionalProperties["ChatOptions"] = chatOptions;

        await foreach (var message in agent.InvokeStreamingAsync(history, options))
        {
            if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Content))
            {
                Console.Write(message.Content);
            }
        }

        Console.WriteLine();
        Console.WriteLine();

        if (tools.Notes.Count > 0)
        {
            Console.ForegroundColor = ConsoleColor.DarkGray;
            Console.WriteLine($"[{tools.Notes.Count} research note(s) saved during this session]");
            Console.ResetColor();
        }
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

